import React, { useEffect, useState } from "react";

/* ============================================================
   TTS Nigeria — V2 prototype (multi-page)
   Pages: Home · About · Stories · Programmes · Insights
   Brand: deep green #004931 / brand green #00B75B / lemon #8FC14E
          yellow #FDC00D / cream #FFF5CC · Bricolage Grotesque + Inter
   Note: "Apply for free" routes to APPLY_URL (placeholder — wire to
   the real application portal). Partner/contact/collaborate → mailto.
   ============================================================ */

const APPLY_URL = "#apply"; // TODO: replace with real application-portal URL
const MAIL = "mailto:partnership@ttsnigeria.org";
const FRAUD = "mailto:report@ttsnigeria.org"; // TODO: confirm fraud-report address
const TAG = "Inclusive opportunities · Local impact · Global relevance";

const IMAGES = {"hero": "data:image/webp;base64,", "women": "data:image/webp;base64,", "bpo-ng": "data:image/webp;base64,", "bpo-intl": "data:image/webp;base64,", "gov-ng": "data:image/webp;base64,", "gov-intl": "data:image/webp;base64,", "story-1": "data:image/webp;base64,", "story-2": "data:image/webp;base64,", "story-3": "data:image/webp;base64,", "partner": "data:image/webp;base64,"};

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400;12..96,600;12..96,700;12..96,800&family=Inter:wght@400;500;600;700&display=swap');
:root{
  --green-900:#003726; --green-800:#004931; --green:#00B75B; --green-600:#009a4c;
  --lemon:#8FC14E; --yellow:#FDC00D; --cream:#FFF5CC; --cream-2:#FBFBEF;
  --ink:#16241d; --muted:#5b6b62; --line:#e7ede9; --white:#fff;
  --r:18px; --r-lg:26px; --max:1160px; --read:680px;
  --disp:'Bricolage Grotesque',system-ui,sans-serif; --body:'Inter',system-ui,sans-serif;
}
*{box-sizing:border-box}
.tts{font-family:var(--body);color:var(--ink);background:var(--white);line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.tts h1,.tts h2,.tts h3,.tts h4{font-family:var(--disp);letter-spacing:-.03em;line-height:1.04;margin:0;font-weight:700}
.tts p{margin:0}
.tts a{color:inherit;text-decoration:none}
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
.eyebrow{font-size:.76rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--green-600)}
.lead{font-size:1.16rem;color:var(--muted)}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:8px;font-weight:600;font-size:.94rem;border-radius:999px;padding:13px 24px;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s,border-color .15s,color .15s}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:var(--green);color:#062f1d}
.btn-primary:hover{background:var(--green-600);color:#fff}
.btn-dark{background:var(--green-800);color:#fff}
.btn-dark:hover{background:var(--green-900)}
.btn-ghost{background:transparent;color:var(--ink);border-color:var(--line)}
.btn-ghost:hover{border-color:var(--green-800);color:var(--green-800)}
.btn-light{background:transparent;color:#fff;border-color:rgba(255,255,255,.32)}
.btn-light:hover{background:rgba(255,255,255,.12)}
.link-arrow{display:inline-flex;align-items:center;gap:6px;font-weight:600;color:var(--green-800)}
.link-arrow:hover{gap:10px;color:var(--green-600)}

/* nav */
.nav{position:sticky;top:0;z-index:60;background:rgba(255,255,255,.9);backdrop-filter:saturate(150%) blur(12px);border-bottom:1px solid var(--line)}
.nav-in{display:flex;align-items:center;justify-content:space-between;height:70px;gap:20px}
.logo{display:flex;align-items:center;gap:11px;font-family:var(--disp);font-weight:800;font-size:1.06rem;letter-spacing:-.02em;cursor:pointer}
.logo small{display:block;font-size:.58rem;font-weight:600;letter-spacing:.2em;color:var(--green);text-transform:uppercase;line-height:1;margin-top:2px}
.nav-mid{display:flex;gap:28px}
.nav-mid button{background:none;border:0;font:inherit;font-size:.93rem;font-weight:500;color:var(--muted);cursor:pointer;padding:0}
.nav-mid button:hover,.nav-mid button.active{color:var(--ink)}
.nav-end{display:flex;align-items:center;gap:10px}
.menu-btn{display:none;background:none;border:0;cursor:pointer;padding:8px}
.menu-btn span{display:block;width:22px;height:2px;background:var(--ink);margin:4px 0;border-radius:2px}

/* ribbon */
.ribbon{background:var(--green-800);color:#eaf7ee}
.ribbon-in{display:flex;align-items:center;justify-content:center;gap:14px;flex-wrap:wrap;padding:11px 24px;font-size:.9rem;text-align:center}
.ribbon b{color:var(--yellow);font-weight:700}
.ribbon a{font-weight:700;color:#fff;border-bottom:1.5px solid var(--green);padding-bottom:1px}
.ribbon a:hover{color:var(--yellow);border-color:var(--yellow)}

/* sections */
.sec{padding:104px 0;scroll-margin-top:80px}
.sec.tight{padding:72px 0}
.cream{background:var(--cream-2)}
.dark{background:var(--green-800);color:#e9f2ec}
.dark h1,.dark h2,.dark h3,.dark h4{color:#fff}
.dark .lead{color:rgba(255,255,255,.8)}
.dark .eyebrow{color:var(--lemon)}
.head{max-width:var(--read)}
.head h2{font-size:clamp(2rem,4vw,2.9rem);margin:14px 0 0}
.head .lead{margin-top:18px}

/* hero */
.hero{padding:96px 0 92px;background:radial-gradient(1100px 480px at 82% -12%,rgba(143,193,78,.2),transparent 62%),linear-gradient(180deg,#fbfdf9,#fff)}
.hero h1{font-size:clamp(2.7rem,6vw,4.6rem);font-weight:800;max-width:14ch}
.hero h1 em{font-style:normal;color:var(--green-600)}
.hero .lead{margin:26px 0;max-width:600px;font-size:1.22rem}
.hero .lead+.lead{margin-top:-6px;font-size:1.06rem}
.hero-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}
.hero-stats{display:flex;gap:40px;flex-wrap:wrap;margin-top:54px;padding-top:32px;border-top:1px solid var(--line)}
.hero-stats .n{font-family:var(--disp);font-weight:800;font-size:2rem;color:var(--green-800);letter-spacing:-.03em;line-height:1}
.hero-stats .l{font-size:.84rem;color:var(--muted);max-width:140px;margin-top:4px}

/* audience */
.aud-intro{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-bottom:8px}
.chips{display:flex;gap:9px;flex-wrap:wrap}
.chip{font-size:.84rem;font-weight:600;padding:9px 15px;border-radius:999px;background:#fff;border:1px solid var(--line);color:var(--green-800);cursor:pointer;transition:.15s}
.chip:hover{border-color:var(--green);background:#f3fbf6}
.aud{padding:84px 0;scroll-margin-top:80px;border-top:1px solid var(--line)}
.aud:first-of-type{border-top:0}
.aud-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:56px;align-items:center}
.aud-grid.flip{direction:rtl}.aud-grid.flip>*{direction:ltr}
.aud .tag-aud{font-size:.76rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--green-600)}
.aud.dark .tag-aud{color:var(--lemon)}
.aud h3{font-size:clamp(1.7rem,3.4vw,2.5rem);margin:12px 0 0;max-width:16ch}
.aud p{margin:18px 0 26px;font-size:1.08rem;color:var(--muted);max-width:48ch}
.aud.dark p{color:rgba(255,255,255,.82)}
.aud-visual{aspect-ratio:4/3.3;border-radius:var(--r-lg);position:relative;overflow:hidden;display:grid;place-items:center}
.v-photo{background:linear-gradient(150deg,var(--green-800),var(--green-900));color:rgba(255,255,255,.55)}
.v-photo::after{content:"";position:absolute;inset:0;background:radial-gradient(120% 90% at 28% 18%,rgba(0,183,91,.34),transparent 60%);mix-blend-mode:screen}
.v-cream{background:var(--cream)}
.v-lemon{background:var(--lemon)}
.v-yellow{background:var(--yellow)}
.v-ph{font-size:.7rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;z-index:1;opacity:.85}
.aud-visual img{width:100%;height:100%;object-fit:cover;display:block}
.hero-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:54px;align-items:center}
.hero-photo{aspect-ratio:4/4.5;border-radius:var(--r-lg);overflow:hidden;background:linear-gradient(150deg,var(--green-800),var(--green-900))}
.hero-photo img{width:100%;height:100%;object-fit:cover;display:block}
.tile .ph{position:relative}.tile .ph img{width:100%;height:100%;object-fit:cover;display:block;position:absolute;inset:0}

/* purpose / vision / mission */
.pvm{display:grid;grid-template-columns:1fr;gap:0}
.purpose{font-family:var(--disp);font-weight:700;font-size:clamp(1.5rem,3.2vw,2.25rem);letter-spacing:-.03em;line-height:1.18;max-width:24ch}
.purpose b{color:var(--green-600);font-weight:700}
.vm{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:48px}
.vm-card{border:1px solid var(--line);border-radius:var(--r-lg);padding:34px;background:#fff}
.vm-card .eyebrow{margin-bottom:12px}
.vm-card h3{font-size:1.35rem}
.vm-card p{color:var(--muted);margin-top:12px}

/* impact */
.band{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,255,255,.14);border-radius:var(--r-lg);overflow:hidden;margin:44px 0}
.band .cell{background:var(--green-800);padding:32px 26px}
.band .n{font-family:var(--disp);font-weight:800;font-size:2.5rem;color:var(--yellow);letter-spacing:-.04em;line-height:1}
.band .l{color:rgba(255,255,255,.82);font-size:.9rem;margin-top:10px;line-height:1.4}
.enables{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px 30px;margin-top:8px}
.enables div{position:relative;padding-left:24px;color:rgba(255,255,255,.85);font-size:.97rem}
.enables div::before{content:"";position:absolute;left:0;top:11px;width:9px;height:9px;border-radius:50%;background:var(--lemon)}
.stake{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}
.stake-card{border:1px solid var(--line);border-radius:var(--r-lg);padding:32px;background:#fff;transition:transform .18s,box-shadow .18s}
.stake-card:hover{transform:translateY(-4px);box-shadow:0 16px 36px rgba(0,73,49,.09)}
.stake-card h4{font-size:1.18rem;color:var(--green-800)}
.stake-card ul{list-style:none;padding:0;margin:16px 0 0;display:grid;gap:11px}
.stake-card li{position:relative;padding-left:22px;color:var(--muted);font-size:.96rem}
.stake-card li::before{content:"";position:absolute;left:0;top:9px;width:7px;height:7px;border-radius:50%;background:var(--green)}
.footprint{display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin-top:46px;padding:30px 34px;background:var(--cream);border-radius:var(--r-lg)}
.footprint .n{font-family:var(--disp);font-weight:800;font-size:2.6rem;color:var(--green-800);letter-spacing:-.04em;line-height:1}
.footprint .l{color:var(--muted);max-width:40ch}

/* fraud */
.fraud{padding:80px 0}
.fraud-card{background:#fff;border:2px solid var(--yellow);border-radius:var(--r-lg);padding:46px;display:grid;grid-template-columns:auto 1fr auto;gap:30px;align-items:center}
.fraud-badge{width:58px;height:58px;border-radius:16px;background:var(--yellow);display:grid;place-items:center;color:#5a4500}
.fraud-badge svg{width:30px;height:30px}
.fraud h3{font-size:1.55rem;color:var(--green-800)}
.fraud p{color:var(--muted);margin-top:8px;font-size:1rem;max-width:62ch}
.fraud b{color:var(--ink)}

/* explore */
.explore{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.exp-card{border:1px solid var(--line);border-radius:var(--r-lg);padding:34px;background:#fff;display:flex;flex-direction:column;gap:14px;transition:transform .18s,box-shadow .18s}
.exp-card:hover{transform:translateY(-4px);box-shadow:0 16px 36px rgba(0,73,49,.09)}
.exp-card .ico{width:48px;height:48px;border-radius:14px;background:#eafaf0;display:grid;place-items:center;color:var(--green-800)}
.exp-card .ico svg{width:24px;height:24px}
.exp-card h3{font-size:1.3rem}
.exp-card p{color:var(--muted);font-size:.97rem;flex:1}

/* final cta */
.fin{text-align:center}
.fin h2{font-size:clamp(2.1rem,4.4vw,3.1rem);max-width:20ch;margin:0 auto}
.fin p{color:rgba(255,255,255,.82);max-width:62ch;margin:22px auto 0;font-size:1.1rem}
.fin .hero-cta{justify-content:center;margin-top:34px}

/* footer */
.foot{background:var(--green-900);color:rgba(255,255,255,.72);padding:64px 0 40px}
.foot-top{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px;padding-bottom:40px;border-bottom:1px solid rgba(255,255,255,.12)}
.foot .tag{font-family:var(--disp);font-weight:700;color:#fff;font-size:1.1rem;letter-spacing:-.02em;margin-top:14px}
.foot h5{color:#fff;font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;font-weight:600;margin:0 0 16px;font-family:var(--body)}
.foot ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}
.foot button,.foot a{background:none;border:0;font:inherit;color:rgba(255,255,255,.72);cursor:pointer;padding:0;text-align:left}
.foot button:hover,.foot a:hover{color:var(--yellow)}
.foot-bot{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:28px;font-size:.84rem}

/* generic page hero */
.phero{padding:88px 0 64px;background:linear-gradient(180deg,#fbfdf9,#fff)}
.phero h1{font-size:clamp(2.3rem,5vw,3.6rem);max-width:18ch}
.phero .lead{margin-top:20px;max-width:60ch}
.cards3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.cards2{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}
.tile{border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;background:#fff}
.tile .ph{aspect-ratio:16/10;background:linear-gradient(150deg,var(--green-800),var(--green-900));display:grid;place-items:center;color:rgba(255,255,255,.5);font-size:.7rem;letter-spacing:.1em;text-transform:uppercase}
.tile .body{padding:26px}
.tile .meta{font-size:.78rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--green-600)}
.tile h3{font-size:1.25rem;margin:8px 0 10px}
.tile p{color:var(--muted);font-size:.95rem}
.scaffold{display:inline-flex;align-items:center;gap:8px;font-size:.78rem;font-weight:600;color:var(--green-600);background:#eafaf0;padding:7px 14px;border-radius:999px}
.signup{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}
.signup input{flex:1;min-width:220px;padding:13px 18px;border:1px solid var(--line);border-radius:999px;font:inherit}
.states{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.state{font-size:.88rem;font-weight:500;padding:9px 16px;border-radius:999px;background:var(--cream);color:var(--green-800)}

.reveal{opacity:0;transform:translateY(22px);transition:opacity .6s,transform .6s}
.reveal.in{opacity:1;transform:none}
:focus-visible{outline:3px solid var(--green);outline-offset:3px;border-radius:6px}

@media (max-width:900px){
  .nav-mid{display:none}
  .nav-mid.open{display:flex;position:absolute;top:70px;left:0;right:0;flex-direction:column;gap:0;background:#fff;border-bottom:1px solid var(--line);padding:6px 24px 16px}
  .nav-mid.open button{padding:13px 0;border-bottom:1px solid var(--line);text-align:left}
  .menu-btn{display:block}
  .nav-end .btn{display:none}
  .nav-end .btn.keep{display:inline-flex}
  .aud-grid,.vm,.stake,.explore,.cards3,.cards2,.foot-top{grid-template-columns:1fr}
  .hero-grid{grid-template-columns:1fr;gap:32px}
  .hero-photo{aspect-ratio:16/11;max-height:360px}
  .aud-grid.flip{direction:ltr}
  .band{grid-template-columns:1fr 1fr}
  .fraud-card{grid-template-columns:1fr;gap:20px;text-align:left}
}
@media (max-width:560px){ .band{grid-template-columns:1fr} .hero-stats{gap:26px} }
@media (prefers-reduced-motion:reduce){ .reveal{transition:none;opacity:1;transform:none} .btn,.stake-card,.exp-card{transition:none} }
`;

